//#region src/lib/settings.ts
var DEFAULT_SETTINGS = {
	taux: 640,
	tarifKg: 7e4,
	fraisPct: 15,
	margeDefaut: 3e4,
	arrondiAuto: true
};
var KEY = "importapro:settings:v1";
var EVT = "importapro:settings:changed";
function getSettings() {
	if (typeof window === "undefined") return DEFAULT_SETTINGS;
	try {
		const raw = window.localStorage.getItem(KEY);
		if (!raw) return DEFAULT_SETTINGS;
		const parsed = JSON.parse(raw);
		return {
			...DEFAULT_SETTINGS,
			...parsed
		};
	} catch {
		return DEFAULT_SETTINGS;
	}
}
function saveSettings(s) {
	if (typeof window === "undefined") return;
	window.localStorage.setItem(KEY, JSON.stringify(s));
	window.dispatchEvent(new CustomEvent(EVT));
}
function onSettingsChange(cb) {
	if (typeof window === "undefined") return () => {};
	const handler = () => cb();
	window.addEventListener(EVT, handler);
	window.addEventListener("storage", handler);
	return () => {
		window.removeEventListener(EVT, handler);
		window.removeEventListener("storage", handler);
	};
}
/** Round to nearest 100 Ar when enabled */
function applyRounding(value, enabled) {
	if (!enabled) return value;
	return Math.round(value / 100) * 100;
}
//#endregion
export { saveSettings as a, onSettingsChange as i, applyRounding as n, getSettings as r, DEFAULT_SETTINGS as t };
